H.background();
const d = P.d, m = P.m, tau = P.tau;
const I = 2 * m * d * d;
const alpha = I > 1e-6 ? tau / I : 0;
const cx = 260, cy = 300, R = 120;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 5, { fill: H.colors.sub });
const tt = (t % 5);
const theta = 0.5 * alpha * tt * tt;
const omega = alpha * tt;
const rPix = 30 + d * 90;
const m1x = cx + rPix * Math.cos(theta), m1y = cy + rPix * Math.sin(theta);
const m2x = cx - rPix * Math.cos(theta), m2y = cy - rPix * Math.sin(theta);
H.line(m1x, m1y, m2x, m2y, { color: H.colors.sub, width: 3 });
const mr = 6 + m * 4;
H.circle(m1x, m1y, mr, { fill: H.colors.accent });
H.circle(m2x, m2y, mr, { fill: H.colors.accent });
const txp = cx + R * Math.cos(theta + Math.PI / 2);
const typ = cy + R * Math.sin(theta + Math.PI / 2);
const ttx = txp + 34 * Math.cos(theta);
const tty = typ + 34 * Math.sin(theta);
H.arrow(txp, typ, ttx, tty, { color: H.colors.accent2, width: 3 });
H.text("same tau", txp + 6, typ - 8, { color: H.colors.accent2, size: 12 });
H.text("Rotational inertia: I = sum(m r^2),  alpha = tau / I", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Slide the masses out: bigger I, so the SAME torque gives a smaller alpha", 24, 50, { color: H.colors.sub, size: 13 });
H.text("d = " + d.toFixed(2) + " m   m = " + m.toFixed(1) + " kg   I = " + I.toFixed(2) + " kg*m^2", 24, 72, { color: H.colors.yellow, size: 13 });
H.text("alpha = tau/I = " + alpha.toFixed(2) + " rad/s^2   omega = " + omega.toFixed(2) + " rad/s", 24, 92, { color: H.colors.good, size: 13 });
